package vn.edu.eaut.lab8.model; import jakarta.validation.constraints.*; public class SinhVien { private int id; @NotBlank(message="Mã sinh viên không được để trống") private String maSinhVien; @NotBlank(message="Họ tên không được để trống") @Size(min=5,message="Họ tên tối thiểu 5 ký tự") private String hoTen; @Email(message="Email không đúng định dạng") private String email; @NotBlank(message="Lớp không được để trống") private String lop; public SinhVien(){} public SinhVien(int i,String m,String h,String e,String l){id=i;maSinhVien=m;hoTen=h;email=e;lop=l;} public int getId(){return id;} public void setId(int v){id=v;} public String getMaSinhVien(){return maSinhVien;} public void setMaSinhVien(String v){maSinhVien=v;} public String getHoTen(){return hoTen;} public void setHoTen(String v){hoTen=v;} public String getEmail(){return email;} public void setEmail(String v){email=v;} public String getLop(){return lop;} public void setLop(String v){lop=v;} }
